def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 70
    MAX_SUPPLY = 25
    MIN_SUPPLY = 15

    supply = day_context['supply']
    day = day_context['day']
    hp = my_status['hp']
    budget = my_status['budget']
    no_water_days = my_status['no_water_days']

    alive = []
    for agent_id, opp in opponents_status.items():
        if opp.get('alive'):
            alive.append(opp)

    if budget <= 0:
        return 0.0

    if not alive:
        if hp <= 2 or no_water_days >= 1:
            return float(min(budget, DAILY_SALARY * 0.75))
        return float(min(budget, DAILY_SALARY * 0.2))

    prev_bids = []
    urgent_opp = 0
    rich_opp = 0
    for opp in alive:
        if opp.get('budget', 0) > budget:
            rich_opp += 1
        if opp.get('hp', 10) <= 3 or opp.get('no_water_days', 0) >= 1:
            urgent_opp += 1
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            try:
                prev_bids.append(float(prev.get('bid', 0.0)))
            except Exception:
                pass

    highest_prev = max(prev_bids) if prev_bids else 0.0
    avg_prev = sum(prev_bids) / len(prev_bids) if prev_bids else 0.0

    scarcity = supply <= WATER_REQ * 1.25
    comfortable_supply = supply >= 22

    if hp <= 2 or no_water_days >= 2:
        bid = max(DAILY_SALARY * 0.92, highest_prev + 2.5)
    elif no_water_days >= 1 or hp <= 4:
        bid = max(DAILY_SALARY * 0.78, highest_prev + 1.6)
    else:
        if scarcity:
            bid = max(DAILY_SALARY * 0.62, highest_prev + 1.2)
        elif comfortable_supply:
            bid = max(DAILY_SALARY * 0.38, avg_prev * 0.92)
        else:
            bid = max(DAILY_SALARY * 0.5, avg_prev + 0.8)

    if urgent_opp >= 2:
        bid += 3.0
    elif urgent_opp == 1:
        bid += 1.5

    if rich_opp >= 2 and hp > 4 and no_water_days == 0:
        bid -= 2.0

    if day >= 8:
        bid += 2.0
    if day >= 9 and (hp <= 4 or no_water_days >= 1):
        bid += 4.0

    reserve_floor = 0.0
    if day < 8:
        reserve_floor = DAILY_SALARY * (10 - day) * 0.18
    max_affordable = max(0.0, budget - reserve_floor)
    if hp <= 3 or no_water_days >= 1:
        max_affordable = budget

    bid = min(bid, max_affordable)
    bid = min(bid, budget)
    bid = max(0.0, bid)
    return float(round(bid, 2))

def get_bid(day_context, my_status, opponents_status):
    WATER_REQ = 13
    DAILY_SALARY = 150

    alive_opponents = [o for o in opponents_status.values() if o['alive']]

    if not alive_opponents:
        return min(my_status['budget'], DAILY_SALARY * 0.1)

    yesterday_bids = []
    for opp in alive_opponents:
        prev = opp.get('previous_trace', {})
        if prev and prev.get('bid') is not None:
            yesterday_bids.append(prev['bid'])

    HIGH_BID_THRESHOLD = DAILY_SALARY * 0.85
    LOW_BID_CONSERVATIVE = DAILY_SALARY * 0.3
    HIGH_BID_DESPERATE = DAILY_SALARY * 0.95
    DEFAULT_STRONG_BID = DAILY_SALARY * 0.5
    CRITICAL_HP_BID = DAILY_SALARY * 0.9

    if yesterday_bids:
        highest_prev_bid = max(yesterday_bids)

        if highest_prev_bid >= HIGH_BID_THRESHOLD:
            if my_status['hp'] > 3:
                return min(my_status['budget'], LOW_BID_CONSERVATIVE)
            return min(my_status['budget'], HIGH_BID_DESPERATE)

        return min(my_status['budget'], max(DEFAULT_STRONG_BID, highest_prev_bid + 1.5))

    if my_status['hp'] <= 2:
        return min(my_status['budget'], CRITICAL_HP_BID)
    return min(my_status['budget'], DEFAULT_STRONG_BID)

